/**
 * Call Flow to Virtual Switchboard hand-off: "open this user (or queue) in the
 * switchboard". Both pages run in the same app instance, so a module-level slot
 * is enough: Call Flow leaves a request and navigates, and the switchboard takes
 * it, once, as it mounts. A request nobody takes within 30 seconds lapses, so a
 * later visit to the switchboard never opens a stale panel.
 */
import type { UserPanelTab } from '../panels/UserPanel';

export type Handoff = { kind: 'user'; user: string; tab: UserPanelTab } | { kind: 'queue'; queue: string };

const TTL_MS = 30_000;
let pending: { handoff: Handoff; at: number } | null = null;

export function leaveHandoff(handoff: Handoff): void {
  pending = { handoff, at: Date.now() };
}

export function takeHandoff(): Handoff | null {
  const p = pending;
  pending = null;
  if (!p || Date.now() - p.at > TTL_MS) return null;
  return p.handoff;
}
