/**
 * Which NetSapiens domain the app's pages look at, shared by the Virtual
 * Switchboard and Call Flow so picking a domain on one carries to the other.
 *
 * Only cross-domain scopes (Admin, Super User, Reseller) may pick. Everyone
 * else is pinned to their own domain: the host can carry a reseller's managed
 * domain into a masquerade, and an Office Manager reading it gets 403 on every
 * request.
 *
 * A pick is remembered per signed-in user (one browser serves a reseller and
 * everyone they masquerade as), together with the domain Horizon itself was
 * managing when it was made. When the user switches domain in Horizon's own
 * switcher the pick is dropped and the app follows Horizon; until then the
 * pick survives page changes and reloads.
 */
import type * as React from 'react';
import { useCallback, useEffect, useState } from 'react';
import type { FlowApiClient } from '@netsapiens/flow-sdk';
import { useFlowContext, useManagingDomain } from '@netsapiens/flow-sdk';

import * as ns from '../api/ns';
import { canPickDomain } from '../model/capabilities';
import type { NsDomain } from '../types';
import { useKit } from '../ui/kit';
import { usePersistentState } from './persist';

interface DomainPick {
  domain: string;
  /** Horizon's managed domain when the pick was made. */
  managing: string;
}

function isPick(v: unknown): v is DomainPick {
  return !!v && typeof v === 'object' && typeof (v as DomainPick).domain === 'string' && typeof (v as DomainPick).managing === 'string';
}

const NO_PICK: DomainPick = { domain: '', managing: '' };

export interface DomainChoice {
  domain: string;
  multiDomain: boolean;
  pick: (domain: string) => void;
}

export function useDomainChoice(): DomainChoice {
  const { user } = useFlowContext();
  const { managing } = useManagingDomain();
  const multiDomain = canPickDomain(user.scope);
  const [picked, setPicked] = usePersistentState<DomainPick>(`domainPick.${user.extension ?? ''}@${user.domain}`, NO_PICK, isPick);
  const hostDomain = managing ?? '';
  const pickHolds = !!picked.domain && picked.managing === hostDomain;
  const domain = multiDomain ? (pickHolds ? picked.domain : hostDomain || user.domain) : user.domain;
  const pick = useCallback((d: string) => setPicked({ domain: d, managing: hostDomain }), [hostDomain, setPicked]);
  return { domain, multiDomain, pick };
}

/** The domain select for cross-domain scopes. */
export function DomainPicker({
  api,
  domain,
  onPick,
  compact,
}: {
  api: FlowApiClient;
  domain: string;
  onPick: (d: string) => void;
  /** No floating label and narrower, for a page header that already says what it is. */
  compact?: boolean;
}) {
  const { Select } = useKit();
  const [domains, setDomains] = useState<NsDomain[] | null>(null);
  useEffect(() => {
    let alive = true;
    ns.readDomains(api)
      .then((rows) => {
        if (!alive) return;
        const list = rows.filter((d) => d.domain).sort((a, b) => String(a.domain).localeCompare(String(b.domain)));
        setDomains(list);
        // A reseller's own domain is often not a customer domain with a
        // switchboard; open the first domain they manage instead of an empty page.
        if (list.length && !list.some((d) => d.domain === domain)) onPick(String(list[0].domain));
      })
      .catch(() => {
        if (alive) setDomains([]);
      });
    return () => {
      alive = false;
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [api]);
  // The host Select prints subLabel inside the closed field too, so the
  // description would run into the domain name there; show the domain only.
  const options = (domains ?? []).map((d) => ({ value: String(d.domain), label: String(d.domain) }));
  if (!options.some((o) => o.value === domain)) options.unshift({ value: domain, label: domain });
  return (
    <Select
      size="small"
      label={compact ? undefined : 'Domain'}
      value={domain}
      onChange={(e: React.ChangeEvent<HTMLInputElement>) => onPick(String(e.target.value))}
      options={options}
      SelectDisplayProps={{ 'aria-label': 'Domain' }}
      sx={compact ? { minWidth: 180, '& .MuiInputBase-input': { py: 0.5, fontSize: 13 } } : { minWidth: 220 }}
    />
  );
}
