/**
 * The host UI kit, resolved once with safe fallbacks.
 *
 * Every visual element comes from `horizonContext.ui` (the host's MUI "Aurora"
 * kit), so the console follows the host theme and light/dark mode with no
 * styling of its own. The kit declares most members optional; `useKit()` hands
 * back a complete set, substituting a plain element for anything an older host
 * does not provide, so a view never has to null-check a component.
 */
import type * as React from 'react';
import { useMemo } from 'react';
import type { FlowUI, FlowUITemplates, HostComponent, HostComponentProps } from '@netsapiens/flow-sdk';
import { useFlowContext } from '@netsapiens/flow-sdk';

type C<K extends keyof FlowUI> = NonNullable<FlowUI[K]>;

export interface Kit {
  Box: HostComponent;
  Stack: HostComponent;
  Typography: HostComponent;
  Chip: HostComponent;
  Avatar: HostComponent;
  Divider: HostComponent;
  Tooltip: HostComponent;
  Button: HostComponent;
  Paper: C<'Paper'>;
  Card: C<'Card'>;
  IconButton: C<'IconButton'>;
  TextField: C<'TextField'>;
  Select: C<'Select'>;
  Tabs: C<'Tabs'>;
  SearchField: C<'SearchField'>;
  Switch: C<'Switch'>;
  Checkbox: C<'Checkbox'>;
  ToggleButtonGroup: C<'ToggleButtonGroup'>;
  Alert: C<'Alert'>;
  StatBlock: C<'StatBlock'>;
  Chart: C<'Chart'>;
  Donut: C<'Donut'>;
  ActivityList: C<'ActivityList'>;
  Table: HostComponent;
  TableHead: HostComponent;
  TableBody: HostComponent;
  TableRow: HostComponent;
  TableCell: HostComponent;
  Icon: FlowUITemplates['Icon'];
  PageTemplate: FlowUITemplates['PageTemplate'];
  SidePanel: FlowUITemplates['SidePanel'];
  DatagridTemplate: FlowUITemplates['DatagridTemplate'];
}

// ---- fallbacks (plain elements; only used when a host lacks a component) ----

const Div: HostComponent = (p: HostComponentProps) => (
  <div className={p.className} style={p.style} id={p.id}>
    {p.children}
  </div>
);
const Span: HostComponent = (p: HostComponentProps) => <span style={p.style}>{p.children}</span>;
const Pass: HostComponent = (p: HostComponentProps) => <>{p.children}</>;
const Hr: HostComponent = () => <hr />;
const FallbackChip: HostComponent = (p: HostComponentProps) => <span>{String(p.label ?? '')}</span>;
const FallbackButton: HostComponent = (p: HostComponentProps) => (
  <button type="button" onClick={p.onClick as React.MouseEventHandler} disabled={Boolean(p.disabled)}>
    {p.children}
  </button>
);
const FallbackIconButton = ((p: { icon: string; 'aria-label'?: string; onClick?: React.MouseEventHandler<HTMLButtonElement>; disabled?: boolean }) => (
  <button type="button" aria-label={p['aria-label']} onClick={p.onClick} disabled={p.disabled}>
    {p['aria-label'] ?? p.icon}
  </button>
)) as unknown as C<'IconButton'>;
const FallbackTextField = ((p: { value?: string | number; placeholder?: unknown; onChange?: React.ChangeEventHandler<HTMLInputElement> }) => (
  <input value={p.value ?? ''} placeholder={typeof p.placeholder === 'string' ? p.placeholder : undefined} onChange={p.onChange} />
)) as unknown as C<'TextField'>;
const FallbackSelect = ((p: { value?: string | number; options: Array<{ value: string | number; label: string }>; onChange?: React.ChangeEventHandler<HTMLSelectElement> }) => (
  <select value={p.value} onChange={p.onChange}>
    {p.options.map((o) => (
      <option key={String(o.value)} value={o.value}>
        {o.label}
      </option>
    ))}
  </select>
)) as unknown as C<'Select'>;
const FallbackTabs = ((p: { options: Array<{ value: string | number; label: string }>; value: string | number; onChange: (v: string | number) => void }) => (
  <div role="tablist">
    {p.options.map((o) => (
      <button key={String(o.value)} role="tab" aria-selected={o.value === p.value} onClick={() => p.onChange(o.value)}>
        {o.label}
      </button>
    ))}
  </div>
)) as unknown as C<'Tabs'>;
const FallbackSearch = ((p: { value: string; placeholder?: string; onChange: (v: string) => void }) => (
  <input type="search" value={p.value} placeholder={p.placeholder} onChange={(e) => p.onChange(e.target.value)} />
)) as unknown as C<'SearchField'>;
const FallbackToggle = ((p: { checked?: boolean; label?: string; disabled?: boolean; onChange?: (e: React.ChangeEvent<HTMLInputElement>, c: boolean) => void }) => (
  <label>
    <input type="checkbox" checked={!!p.checked} disabled={p.disabled} onChange={(e) => p.onChange?.(e, e.target.checked)} />
    {p.label}
  </label>
)) as unknown as C<'Switch'>;
const FallbackToggleGroup = ((p: { options: Array<{ value: string | number; label: string }>; value?: unknown; onChange?: (e: unknown, v: unknown) => void }) => (
  <div>
    {p.options.map((o) => (
      <button key={String(o.value)} aria-pressed={o.value === p.value} onClick={(e) => p.onChange?.(e, o.value)}>
        {o.label}
      </button>
    ))}
  </div>
)) as unknown as C<'ToggleButtonGroup'>;
const FallbackAlert = ((p: { severity: string; title?: string; message?: string; children?: React.ReactNode }) => (
  <div role={p.severity === 'error' ? 'alert' : 'status'}>
    {p.title ? <strong>{p.title} </strong> : null}
    {p.message}
    {p.children}
  </div>
)) as unknown as C<'Alert'>;
const FallbackStat = ((p: { value: number | string; caption?: string }) => (
  <div>
    <strong>{p.value}</strong> {p.caption}
  </div>
)) as unknown as C<'StatBlock'>;
const FallbackNone = (() => null) as unknown;
const FallbackActivity = ((p: { rows: Array<{ id: string; primary: string; secondary?: string; meta?: string }>; emptyMessage?: string }) =>
  p.rows.length ? (
    <ul>
      {p.rows.map((r) => (
        <li key={r.id}>
          {r.primary} {r.secondary} {r.meta}
        </li>
      ))}
    </ul>
  ) : (
    <p>{p.emptyMessage}</p>
  )) as unknown as C<'ActivityList'>;
const FallbackIcon = (() => null) as unknown as FlowUITemplates['Icon'];
const FallbackPage = ((p: { title: string; subtitle?: string; children: React.ReactNode }) => (
  <div style={{ padding: 16 }}>
    <h1>{p.title}</h1>
    {p.subtitle ? <p>{p.subtitle}</p> : null}
    {p.children}
  </div>
)) as unknown as FlowUITemplates['PageTemplate'];
const FallbackSidePanel = ((p: { open: boolean; title: React.ReactNode; onClose: () => void; children: React.ReactNode; footer?: React.ReactNode }) =>
  p.open ? (
    <div role="dialog" aria-modal="true">
      <h2>{p.title}</h2>
      <button type="button" onClick={p.onClose}>
        Close
      </button>
      {p.children}
      {p.footer}
    </div>
  ) : null) as unknown as FlowUITemplates['SidePanel'];
const FallbackGrid = (<TRow,>(p: { data: TRow[]; columns: Array<{ field: string; headerName: string }> }) => (
  <table>
    <thead>
      <tr>
        {p.columns.map((c) => (
          <th key={c.field}>{c.headerName}</th>
        ))}
      </tr>
    </thead>
    <tbody>
      {p.data.map((row, i) => (
        <tr key={i}>
          {p.columns.map((c) => (
            <td key={c.field}>{String((row as Record<string, unknown>)[c.field] ?? '')}</td>
          ))}
        </tr>
      ))}
    </tbody>
  </table>
)) as unknown as FlowUITemplates['DatagridTemplate'];

export function buildKit(ui: FlowUI | undefined): Kit {
  const u = (ui ?? {}) as Partial<FlowUI>;
  const t = (u.templates ?? {}) as Partial<FlowUITemplates>;
  return {
    Box: u.Box ?? Div,
    Stack: u.Stack ?? Div,
    Typography: u.Typography ?? Span,
    Chip: u.Chip ?? FallbackChip,
    Avatar: u.Avatar ?? Span,
    Divider: u.Divider ?? Hr,
    Tooltip: u.Tooltip ?? Pass,
    Button: u.Button ?? FallbackButton,
    Paper: u.Paper ?? (Div as unknown as C<'Paper'>),
    Card: u.Card ?? (Div as unknown as C<'Card'>),
    IconButton: u.IconButton ?? FallbackIconButton,
    TextField: u.TextField ?? FallbackTextField,
    Select: u.Select ?? FallbackSelect,
    Tabs: u.Tabs ?? FallbackTabs,
    SearchField: u.SearchField ?? FallbackSearch,
    Switch: u.Switch ?? FallbackToggle,
    Checkbox: u.Checkbox ?? (FallbackToggle as unknown as C<'Checkbox'>),
    ToggleButtonGroup: u.ToggleButtonGroup ?? FallbackToggleGroup,
    Alert: u.Alert ?? FallbackAlert,
    StatBlock: u.StatBlock ?? FallbackStat,
    Chart: u.Chart ?? (FallbackNone as C<'Chart'>),
    Donut: u.Donut ?? (FallbackNone as C<'Donut'>),
    ActivityList: u.ActivityList ?? FallbackActivity,
    Table: u.Table ?? ((p: HostComponentProps) => <table>{p.children}</table>),
    TableHead: u.TableHead ?? ((p: HostComponentProps) => <thead>{p.children}</thead>),
    TableBody: u.TableBody ?? ((p: HostComponentProps) => <tbody>{p.children}</tbody>),
    TableRow: u.TableRow ?? ((p: HostComponentProps) => <tr>{p.children}</tr>),
    TableCell: u.TableCell ?? ((p: HostComponentProps) => <td>{p.children}</td>),
    Icon: t.Icon ?? FallbackIcon,
    PageTemplate: t.PageTemplate ?? FallbackPage,
    SidePanel: t.SidePanel ?? FallbackSidePanel,
    DatagridTemplate: t.DatagridTemplate ?? FallbackGrid,
  };
}

export function useKit(): Kit {
  const { ui } = useFlowContext();
  return useMemo(() => buildKit(ui), [ui]);
}
