/**
 * A one-row page header, used instead of the host's PageTemplate.
 *
 * The template draws a breadcrumb, a large title and a subtitle on separate
 * lines, about 190 px before any content, and has no compact option. This keeps
 * its 'fill' layout (a full-height flex column whose body takes the leftover
 * height, as the host's own page component does) with everything the header
 * carries on one row that wraps on narrow screens.
 */
import type * as React from 'react';

import type { ZoneMarkerProps } from '../App';
import { useKit } from './kit';

export function CompactPage({
  marker,
  title,
  subtitle,
  subtitleControl,
  start,
  end,
  loading,
  children,
}: {
  marker?: ZoneMarkerProps;
  title: string;
  /** Shown beside the title, smaller (the domain). */
  subtitle?: string;
  /** Replaces the subtitle, e.g. a compact domain picker. */
  subtitleControl?: React.ReactNode;
  /** Right after the title: mode tabs and the like. */
  start?: React.ReactNode;
  /** Pushed to the right edge: totals, status, actions. */
  end?: React.ReactNode;
  loading?: boolean;
  children: React.ReactNode;
}) {
  const { Box, Stack, Typography } = useKit();
  return (
    <Box {...marker} sx={{ height: '100%', minHeight: 0, display: 'flex', flexDirection: 'column' }}>
      <Stack
        component="header"
        direction="row"
        alignItems="center"
        flexWrap="wrap"
        sx={{ flex: 'none', columnGap: 2, rowGap: 1, px: { xs: 2, md: 3 }, py: 1, borderBottom: 1, borderColor: 'divider' }}
      >
        <Stack direction="row" alignItems={subtitleControl ? 'center' : 'baseline'} spacing={1} sx={{ minWidth: 0 }}>
          <Typography component="h1" sx={{ fontSize: 18, fontWeight: 700, lineHeight: 1.3, whiteSpace: 'nowrap' }}>
            {title}
          </Typography>
          {subtitleControl ?? (subtitle ? (
            <Typography sx={{ fontSize: 13, color: 'text.secondary', whiteSpace: 'nowrap', overflow: 'hidden', textOverflow: 'ellipsis' }}>
              {subtitle}
            </Typography>
          ) : null)}
        </Stack>
        {start}
        <Box sx={{ flex: 1 }} />
        {end}
      </Stack>
      <Box sx={{ flex: 1, minHeight: 0, display: 'flex', flexDirection: 'column', px: { xs: 2, md: 3 }, pt: 1.5, pb: 1.5 }}>
        {loading ? (
          <Box sx={{ flex: 1, display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'text.secondary' }}>Loading...</Box>
        ) : (
          children
        )}
      </Box>
    </Box>
  );
}
