/**
 * Analyze: pure mapping from the NetSapiens v2 statistics endpoints to report
 * rows, and the rules each figure follows.
 *
 * Shapes were read off live responses from a v46 switch,
 * not taken from documentation:
 *
 *   statistics/callqueues/per-queue   { "<queue ext>": { name, calls-total-count,
 *       calls-answered-count, calls-abandoned-count, calls-queueing-avg-duration-seconds,
 *       calls-talking-avg-duration-minutes, calls-service-level-percent } }
 *   statistics/callqueues/aggregate   the same six figures for the whole domain
 *   statistics/agent                  { "<agent ext>": { name, calls-answered-count,
 *       calls-talking-avg-duration-minutes, calls-talking-duration-minutes,
 *       calls-holding-avg-duration-seconds, calls-handling-avg-duration-minutes } }
 *   callqueuereport/abandoned         [ { orig_callid, cdr_id, callqueue, op_term_sub,
 *       orig_from_name, orig_from_user, dnis, queue_time_start (naive UTC),
 *       queue_duration (s), queue_rel_text, op_rel_text, ... } ]
 *   statistics/dnis                   { "<dialed number>": { calls-total-count,
 *       calls-answered-count, calls-talking-avg-duration-minutes,
 *       calls-holding-avg-duration-seconds } }
 *
 * An empty window answers zeroed rows for queues and agents, `[]` for the
 * abandoned report, and `[]` (an array, not `{}`) for DNIS.
 */
import type { NsRecord } from '../../types';
import type { Tone } from '../../ui/bits';
import { usefulCallerName } from '../../model/calls';
import { formatPhone } from '../../model/format';
import { cleanNumber, first, parseSwitchTime, pick, str, toFloat, toInt } from '../../model/raw';

export type AnalyzeTab = 'queues' | 'agents' | 'abandoned' | 'dnis' | 'history';

export const ANALYZE_TABS: Array<{ value: AnalyzeTab; label: string; icon: string }> = [
  { value: 'queues', label: 'Queue performance', icon: 'lucide:chart-column' },
  { value: 'agents', label: 'Agent performance', icon: 'lucide:users' },
  { value: 'abandoned', label: 'Abandoned calls', icon: 'lucide:phone-off' },
  { value: 'dnis', label: 'Dialed numbers', icon: 'lucide:hash' },
  { value: 'history', label: 'Call history', icon: 'lucide:history' },
];

function has(rec: NsRecord, key: string): boolean {
  return rec[key] != null && str(rec[key]).trim() !== '';
}

function records(raw: Record<string, NsRecord> | null | undefined): Array<[string, NsRecord]> {
  if (!raw || typeof raw !== 'object') return [];
  return Object.entries(raw).filter(
    (e): e is [string, NsRecord] => !!e[0] && !!e[1] && typeof e[1] === 'object' && !Array.isArray(e[1]),
  );
}

const byExt = (a: { ext: string }, b: { ext: string }) => a.ext.localeCompare(b.ext, undefined, { numeric: true });

// ---------------------------------------------------------------------------
// Queues
// ---------------------------------------------------------------------------

export interface QueueStatRow {
  ext: string;
  name: string;
  offered: number;
  answered: number;
  abandoned: number;
  /** Answered over offered (0 to 1), or null when nothing was offered. */
  answerRate: number | null;
  avgWaitSeconds: number;
  avgTalkSeconds: number;
  /** The switch's per-queue service level (0 to 100), or null when nothing was offered. */
  serviceLevel: number | null;
}

export function mapQueueStats(
  raw: Record<string, NsRecord> | null | undefined,
  names: ReadonlyMap<string, string>,
): QueueStatRow[] {
  return records(raw)
    .map(([ext, r]) => {
      const offered = toInt(r['calls-total-count']);
      const answered = toInt(r['calls-answered-count']);
      return {
        ext,
        name: first(r.name, names.get(ext), ext),
        offered,
        answered,
        abandoned: toInt(r['calls-abandoned-count']),
        answerRate: offered > 0 ? answered / offered : null,
        avgWaitSeconds: toFloat(r['calls-queueing-avg-duration-seconds']),
        // The queue report gives talk time in MINUTES (1.34 = 1:20).
        avgTalkSeconds: toFloat(r['calls-talking-avg-duration-minutes']) * 60,
        serviceLevel:
          offered > 0 && has(r, 'calls-service-level-percent') ? toFloat(r['calls-service-level-percent']) : null,
      };
    })
    .sort(byExt);
}

/** Answer-rate banding: below 80% is critical, below 90% needs watching. */
export function answerRateTone(rate: number | null): Tone {
  if (rate == null) return 'neutral';
  if (rate < 0.8) return 'error';
  if (rate < 0.9) return 'warning';
  return 'success';
}

export interface QueueTotals {
  offered: number;
  answered: number;
  abandoned: number;
  answerRate: number | null;
  /** Weighted by calls offered, never a mean of the queue means. */
  avgWaitSeconds: number;
  /** The domain service level (0 to 100), or null when the switch gave no trustworthy one. */
  serviceLevel: number | null;
}

/**
 * The KPI row. Every count is the sum of the queue rows beneath it, so the
 * tiles and the table can never give two answers to one question.
 *
 * The domain aggregate is NOT used for the counts, on evidence: on the v46
 * lab it agrees with the per-queue sums for recent windows (today, yesterday,
 * the last 7, 14 and 21 days all reconciled exactly, average wait included),
 * but for a window reaching back before early September it returned 525
 * offered and 133 answered against per-queue sums of 662 and 486, and for
 * one older window 133 answered out of 67 offered. The per-queue report
 * stayed consistent throughout.
 *
 * The service level is the one figure the rows cannot rebuild: the per-queue
 * value and the domain value are computed differently by the switch (every
 * lab queue reads 100% on days its domain reads 80%). So the domain figure is
 * taken from the aggregate, and only when the aggregate's own counts match the
 * rows exactly, which is the case where it has been shown to be right.
 */
export function queueTotals(rows: readonly QueueStatRow[], aggregate: NsRecord | null): QueueTotals {
  const offered = rows.reduce((n, r) => n + r.offered, 0);
  const answered = rows.reduce((n, r) => n + r.answered, 0);
  const abandoned = rows.reduce((n, r) => n + r.abandoned, 0);
  const waitWeighted = rows.reduce((n, r) => n + r.avgWaitSeconds * r.offered, 0);
  let serviceLevel: number | null = null;
  if (
    aggregate &&
    offered > 0 &&
    has(aggregate, 'calls-service-level-percent') &&
    toInt(aggregate['calls-total-count']) === offered &&
    toInt(aggregate['calls-answered-count']) === answered &&
    toInt(aggregate['calls-abandoned-count']) === abandoned
  ) {
    serviceLevel = toFloat(aggregate['calls-service-level-percent']);
  }
  return {
    offered,
    answered,
    abandoned,
    answerRate: offered > 0 ? answered / offered : null,
    avgWaitSeconds: offered > 0 ? waitWeighted / offered : 0,
    serviceLevel,
  };
}

// ---------------------------------------------------------------------------
// Agents
// ---------------------------------------------------------------------------

export interface AgentStatRow {
  ext: string;
  name: string;
  answered: number;
  avgTalkSeconds: number;
  talkSeconds: number;
  avgHoldSeconds: number;
  avgHandleSeconds: number;
}

/** Figures exactly as the switch reports them (talk in minutes, hold in seconds). */
export function mapAgentStats(
  raw: Record<string, NsRecord> | null | undefined,
  names: ReadonlyMap<string, string>,
): AgentStatRow[] {
  return records(raw)
    .map(([ext, r]) => ({
      ext,
      name: first(r.name, names.get(ext), ext),
      answered: toInt(r['calls-answered-count']),
      avgTalkSeconds: toFloat(r['calls-talking-avg-duration-minutes']) * 60,
      talkSeconds: toFloat(r['calls-talking-duration-minutes']) * 60,
      avgHoldSeconds: toFloat(r['calls-holding-avg-duration-seconds']),
      avgHandleSeconds: toFloat(r['calls-handling-avg-duration-minutes']) * 60,
    }))
    .sort((a, b) => b.answered - a.answered || byExt(a, b));
}

// ---------------------------------------------------------------------------
// Abandoned calls
// ---------------------------------------------------------------------------

export interface AbandonedRow {
  id: string;
  /** When the caller entered the queue (epoch ms). */
  at: number | null;
  queueExt: string;
  queueName: string;
  /** A name worth showing, or '' when the switch sent none (or only junk). */
  callerName: string;
  /** Formatted caller number. */
  callerNumber: string;
  waitedSeconds: number;
  /** The queue leg's release text, shown as the switch wrote it (never interpreted). */
  reason: string;
  /** The agent leg's release text, when there is one. */
  agentReason: string;
  /** Formatted number the caller dialed. */
  dialed: string;
}

/**
 * `callqueue` is empty on some lab rows; the queue extension is then in
 * `op_term_sub` (the row's agent name fields carry the queue's own name,
 * "Support Queue"). `op_term_sub` is only trusted as the queue when it IS a
 * known queue extension, since on an agent leg it names the agent.
 */
export function mapAbandoned(rows: readonly NsRecord[] | null | undefined, queueNames: ReadonlyMap<string, string>): AbandonedRow[] {
  const seen = new Set<string>();
  const out: AbandonedRow[] = [];
  (rows ?? []).forEach((r, i) => {
    if (!r || typeof r !== 'object') return;
    const sub = pick(r, 'op_term_sub');
    const queueExt = pick(r, 'callqueue') || (queueNames.has(sub) ? sub : '');
    const number = cleanNumber(pick(r, 'orig_from_user', 'orig_from_uri'));
    const rawName = pick(r, 'orig_from_name').replace(/\s+/g, ' ');
    let id = pick(r, 'orig_callid', 'cdr_id', 'term_callid') || `abandoned-${i}`;
    if (seen.has(id)) id = `${id}#${i}`;
    seen.add(id);
    out.push({
      id,
      at: parseSwitchTime(pick(r, 'queue_time_start', 'op_time_start')),
      queueExt,
      queueName: queueExt ? queueNames.get(queueExt) ?? '' : '',
      callerName: usefulCallerName(rawName, number) ? rawName : '',
      callerNumber: formatPhone(number),
      waitedSeconds: toFloat(r.queue_duration),
      reason: pick(r, 'queue_rel_text'),
      agentReason: pick(r, 'op_rel_text'),
      dialed: formatPhone(cleanNumber(pick(r, 'dnis'))),
    });
  });
  return out.sort((a, b) => (b.at ?? 0) - (a.at ?? 0));
}

// ---------------------------------------------------------------------------
// Dialed numbers (DNIS)
// ---------------------------------------------------------------------------

export interface DnisRow {
  /** The raw dialed number (the grid formats it). */
  number: string;
  offered: number;
  answered: number;
  avgTalkSeconds: number;
  avgHoldSeconds: number;
}

/**
 * Whether the DNIS talk average is in seconds.
 *
 * The field is named `calls-talking-avg-duration-minutes`, but the v46 lab
 * puts SECONDS in it: 84 on a day whose queue report averaged 1.4 minutes of
 * talk over the same calls, and 77.8 to 82.1 across a week that averaged 1.3
 * to 1.4 minutes. The unit is chosen by whichever reading agrees with the
 * queue report for the same window (they measure the same calls), so a switch
 * that labels it honestly reads correctly too. With nothing to compare against,
 * seconds, which is what the lab sends. Guessing wrong is a factor of sixty,
 * so a fixed assumption would not be safe in either direction.
 */
export function dnisTalkIsSeconds(raw: Record<string, NsRecord> | null | undefined, queues: readonly QueueStatRow[]): boolean {
  const weighted = (pairs: Array<[number, number]>): number => {
    let sum = 0;
    let weight = 0;
    for (const [value, n] of pairs) {
      if (n > 0 && value > 0) {
        sum += value * n;
        weight += n;
      }
    }
    return weight > 0 ? sum / weight : 0;
  };
  const dnisAvg = weighted(
    records(raw).map(([, r]) => [toFloat(r['calls-talking-avg-duration-minutes']), toInt(r['calls-answered-count'])]),
  );
  const queueAvgMinutes = weighted(queues.map((q) => [q.avgTalkSeconds / 60, q.answered]));
  if (dnisAvg <= 0 || queueAvgMinutes <= 0) return true;
  return Math.abs(Math.log(dnisAvg / 60 / queueAvgMinutes)) < Math.abs(Math.log(dnisAvg / queueAvgMinutes));
}

export function mapDnis(raw: Record<string, NsRecord> | null | undefined, talkIsSeconds: boolean): DnisRow[] {
  return records(raw)
    .map(([number, r]) => {
      const talk = toFloat(r['calls-talking-avg-duration-minutes']);
      return {
        number,
        offered: toInt(r['calls-total-count']),
        answered: toInt(r['calls-answered-count']),
        avgTalkSeconds: talkIsSeconds ? talk : talk * 60,
        avgHoldSeconds: toFloat(r['calls-holding-avg-duration-seconds']),
      };
    })
    .sort((a, b) => b.offered - a.offered || a.number.localeCompare(b.number, undefined, { numeric: true }));
}
