/**
 * A call queue on the Real-Time board (the Engage QueueTile): waiting and
 * answered callers with wait bands, and the agent roster with ring strategy,
 * state, headset and "Staff this queue". Also used inside the expanded-queue
 * panel (`QueueCallerList`, `QueueAgentList`).
 */
import { useEffect, useRef, useState } from 'react';

import type { QueueCaller, QueueMember, QueueView } from '../../types';
import { useSwitchboard } from '../../data/SwitchboardData';
import { usePanels } from '../../data/panels';
import { useNow } from '../../data/clock';
import { BLOCKED } from '../../api/ns';
import { AGENT_STATE, HEADSET, headsetStateFor, resolveAgentState, routableCount } from '../../model/agents';
import { callerWaitSeconds } from '../../model/calls';
import { formatPhone, formatTimer, secondsSince } from '../../model/format';
import { longestWaitSeconds, ringStrategyLabel, showsEntryOrder, waitBand, waitingCount } from '../../model/queues';
import { useKit } from '../../ui/kit';
import { ActionIcon, BlockedButton, Dot, Empty, SmallButton, tint, toneColor, toneText } from '../../ui/bits';

export function queueAgentCounts(q: QueueView, dndByUser: Map<string, boolean>): { available: number; total: number } {
  if (q.roster) return { available: routableCount(q.roster, dndByUser), total: q.roster.length };
  return { available: q.agentsAvailable, total: q.agentsTotal };
}

export function QueueTile({ queue, pinned, onTogglePin }: { queue: QueueView; pinned: boolean; onTogglePin: () => void }) {
  const now = useNow();
  const { Paper, Stack, Typography, Box, Tabs, Tooltip } = useKit();
  const sb = useSwitchboard();
  const { openQueue } = usePanels();
  const [tab, setTab] = useState<'calls' | 'agents'>('calls');
  const dnd = new Map(sb.contacts.map((c) => [c.user, c.dnd] as const));
  const { available, total } = queueAgentCounts(queue, dnd);
  const waiting = waitingCount(queue);
  const hasWaiting = waiting > 0;
  const band = waitBand(longestWaitSeconds(queue, now));
  const realCallers = queue.waiting.filter((c) => !c.placeholder).length + queue.active.length;
  const displayCount = realCallers > 0 ? realCallers : queue.reportedWaiting;
  const label = `${queue.ext} - ${queue.description || 'Unnamed Queue'}`;

  // The Agents tab needs the roster; ask for it the first time the tab opens.
  const { reloadRoster } = sb;
  const asked = useRef(false);
  useEffect(() => {
    if (tab === 'agents' && !queue.roster && !asked.current) {
      asked.current = true;
      void reloadRoster(queue.ext);
    }
  }, [queue.ext, queue.roster, reloadRoster, tab]);

  return (
    <Paper
      variant="outlined"
      title={`Queue ${queue.ext} - ${queue.description || 'Unnamed Queue'}. ${displayCount} call${displayCount === 1 ? '' : 's'}, ${available}/${total} agents available.`}
      sx={{
        width: 480,
        maxWidth: '100%',
        overflow: 'hidden',
        borderLeftWidth: 4,
        borderLeftColor: hasWaiting ? 'warning.main' : 'success.main',
        borderColor: band === 'critical' ? tint('error', 0.35) : band === 'long' ? tint('warning', 0.35) : 'divider',
        boxShadow: band === 'critical' ? 3 : band === 'long' ? 2 : 0,
      }}
    >
      <Stack direction="row" alignItems="center" spacing={0.5} sx={{ px: 1.5, py: 1, borderBottom: 1, borderColor: 'divider' }}>
        <Typography
          variant="subtitle2"
          sx={{ fontWeight: 700, flex: 1, minWidth: 0 }}
          noWrap
          title={`Queue extension: ${queue.ext}. Description: ${queue.description || 'N/A'}. Domain: ${sb.domain}`}
        >
          {label}
        </Typography>
        <ActionIcon icon="lucide:star" label={pinned ? 'Unpin' : 'Pin to top'} color={pinned ? 'warning' : 'default'} onClick={onTogglePin} />
        <ActionIcon icon="lucide:maximize-2" label="Expand queue" onClick={() => openQueue(queue.ext)} />
        <Tooltip
          title={
            hasWaiting
              ? `${waiting} call${waiting === 1 ? '' : 's'} waiting in queue, agents are being dispatched`
              : 'Queue is idle, no calls currently waiting'
          }
          arrow
        >
          <Box sx={{ display: 'flex', px: 0.5 }}>
            <Dot tone={hasWaiting ? 'warning' : 'success'} pulse={hasWaiting} />
          </Box>
        </Tooltip>
      </Stack>
      <Tabs
        variant="standard"
        fullWidth
        value={tab}
        onChange={(v) => setTab(v === 'agents' ? 'agents' : 'calls')}
        options={[
          { value: 'calls', label: `Active & Waiting (${displayCount})` },
          { value: 'agents', label: `Agents (${available}/${total})` },
        ]}
      />
      <Box sx={{ px: 1.5, py: 1.25, minHeight: 64 }}>
        {tab === 'calls' ? <QueueCallerList queue={queue} /> : <QueueAgentList queue={queue} />}
      </Box>
    </Paper>
  );
}

export function QueueCallerList({ queue, max }: { queue: QueueView; max?: number }) {
  const { Stack, Typography, Divider } = useKit();
  const waiting = queue.waiting.slice(0, max ?? queue.waiting.length);
  const active = queue.active;
  if (!waiting.length && !active.length) {
    return <Empty>No calls</Empty>;
  }
  return (
    <Stack spacing={0.75}>
      {waiting.map((c) => (
        <CallerRow key={c.key} caller={c} />
      ))}
      {waiting.length && active.length ? (
        <Divider textAlign="left">
          <Typography sx={{ fontSize: 10, fontWeight: 800, letterSpacing: 1, color: 'text.secondary' }}>ACTIVE</Typography>
        </Divider>
      ) : null}
      {active.map((c) => (
        <CallerRow key={c.key} caller={c} />
      ))}
    </Stack>
  );
}

function CallerRow({ caller }: { caller: QueueCaller }) {
  const now = useNow();
  const { Box, Stack, Typography, Icon } = useKit();
  const tone = caller.isActive ? 'success' : 'warning';
  const wait = callerWaitSeconds(caller, now);
  const band = waitBand(wait);
  const since = caller.isActive ? caller.answeredAt : caller.startedAt;
  const seconds = since != null ? secondsSince(since, now) : wait;
  const timerColor = caller.isActive ? 'success.main' : band === 'critical' ? 'error.main' : band === 'long' ? 'warning.dark' : 'success.main';
  const number = caller.callerNumber;
  const showNumber = !!number && number !== caller.callerName;
  return (
    <Box
      title={
        caller.isActive
          ? `Active call, answered by ${caller.agentName || caller.agentUser || 'agent'}`
          : caller.placeholder
            ? 'Caller waiting in queue'
            : `Waiting in queue${caller.startedAt ? ` since ${new Date(caller.startedAt).toLocaleTimeString()}` : ''}`
      }
      sx={{ px: 1, py: 0.75, borderRadius: 1, border: 1, borderColor: tint(tone, 0.25), bgcolor: tint(tone, 0.08) }}
    >
      <Stack direction="row" spacing={1} alignItems="center">
        <Box sx={{ display: 'flex', color: toneColor(tone) }}>
          <Icon name={caller.isActive ? 'lucide:phone' : 'lucide:phone-incoming'} size={15} />
        </Box>
        <Box sx={{ flex: 1, minWidth: 0 }}>
          <Typography variant="body2" sx={{ fontWeight: 600 }} noWrap title={caller.callerName}>
            {caller.callerName}
          </Typography>
          {showNumber ? (
            <Typography variant="caption" color="text.secondary" sx={{ display: 'block', fontVariantNumeric: 'tabular-nums' }} noWrap>
              {formatPhone(number)}
            </Typography>
          ) : null}
        </Box>
        {caller.isActive ? (
          <Typography variant="caption" color="text.secondary" noWrap sx={{ maxWidth: 110 }}>
            {caller.agentName || caller.agentUser}
          </Typography>
        ) : null}
        {!caller.placeholder ? (
          <Typography
            variant="caption"
            sx={{
              fontVariantNumeric: 'tabular-nums',
              fontWeight: band === 'critical' ? 800 : band === 'long' ? 700 : 500,
              color: timerColor,
              minWidth: 44,
              textAlign: 'right',
            }}
          >
            {formatTimer(seconds)}
          </Typography>
        ) : null}
        {!caller.isActive && !caller.placeholder ? <BlockedButton icon="lucide:phone-call" label="Pickup" reason={BLOCKED.pickup} /> : null}
      </Stack>
    </Box>
  );
}

export function QueueAgentList({ queue }: { queue: QueueView }) {
  const { Stack, Typography, Box } = useKit();
  const sb = useSwitchboard();
  const { openStaffing } = usePanels();
  const dnd = new Map(sb.contacts.map((c) => [c.user, c.dnd] as const));
  const ring = ringStrategyLabel(queue.dispatchType);
  const ordered = showsEntryOrder(queue.dispatchType);

  const staff = (
    <SmallButton variant="text" icon="lucide:user-plus" label="Staff this queue" onClick={() => openStaffing(queue.ext)} />
  );

  if (!queue.roster) {
    return (
      <Stack spacing={1}>
        <Typography variant="body2" color="text.secondary">
          {queue.rosterError ?? 'Loading agents...'}
        </Typography>
        <Typography variant="caption" color="text.secondary">
          {queue.agentsTotal > 0 ? `${queue.agentsAvailable} of ${queue.agentsTotal} agents available` : 'No agents assigned'}
        </Typography>
        <Box>{staff}</Box>
      </Stack>
    );
  }

  const rows = [...queue.roster].sort((a, b) => {
    const ao = a.entryOrder ?? Number.MAX_SAFE_INTEGER;
    const bo = b.entryOrder ?? Number.MAX_SAFE_INTEGER;
    return ao - bo || a.name.localeCompare(b.name);
  });
  const available = routableCount(queue.roster, dnd);

  return (
    <Stack spacing={0.75}>
      {ring ? (
        <Typography sx={{ fontSize: 10, fontWeight: 800, letterSpacing: 1, color: 'text.secondary', textTransform: 'uppercase' }}>
          {ring}
        </Typography>
      ) : null}
      <Stack direction="row" alignItems="center" justifyContent="space-between">
        <Typography variant="caption" color="text.secondary">
          {available} available / {queue.roster.length} total
        </Typography>
        {staff}
      </Stack>
      {rows.length === 0 ? (
        <Empty>No agents assigned</Empty>
      ) : (
        rows.map((m) => <AgentRowItem key={`${m.queue}:${m.user}`} member={m} ordered={ordered} dnd={dnd.get(m.user) ?? false} />)
      )}
    </Stack>
  );
}

function AgentRowItem({ member, ordered, dnd }: { member: QueueMember; ordered: boolean; dnd: boolean }) {
  const { Box, Stack, Typography, Icon, Tooltip } = useKit();
  const sb = useSwitchboard();
  const { openAgentQueues } = usePanels();
  const contact = sb.contactsByUser.get(member.user);
  const state = resolveAgentState([], member.status, { dnd, loggedOut: member.loggedOut, offline: false });
  const info = AGENT_STATE[state];
  const presence = member.loggedOut ? 'closed' : member.activeCalls > 0 ? 'inuse' : 'open';
  const headset = headsetStateFor(presence, { available: member.status === 'available', sessions: member.activeCalls }, member.hasDevice);
  const line = contact?.lines[0];
  const peer = line ? line.peerName || formatPhone(line.peerNumber) : '';
  return (
    <Box
      title={`${member.user}: ${info.label}`}
      sx={{ px: 1, py: 0.75, borderRadius: 1, border: 1, borderColor: 'divider', bgcolor: 'action.hover' }}
    >
      <Stack direction="row" spacing={1} alignItems="center">
        {ordered && member.entryOrder != null ? (
          <Box
            sx={{
              width: 20,
              height: 20,
              borderRadius: '50%',
              bgcolor: tint('primary', 0.15),
              color: 'primary.main',
              fontSize: 11,
              fontWeight: 800,
              display: 'grid',
              placeItems: 'center',
              flexShrink: 0,
            }}
          >
            {member.entryOrder + 1}
          </Box>
        ) : null}
        <Dot tone={info.tone} />
        <Box sx={{ flex: 1, minWidth: 0 }}>
          <Typography variant="body2" sx={{ fontWeight: 600 }} noWrap>
            {member.name}{' '}
            <Box component="span" sx={{ color: 'text.secondary', fontWeight: 400 }}>
              ({member.user})
            </Box>
          </Typography>
          {peer || member.portalStatus ? (
            <Typography variant="caption" color="text.secondary" noWrap sx={{ display: 'block' }}>
              {[peer ? `With ${peer}` : '', member.portalStatus].filter(Boolean).join(' · ')}
            </Typography>
          ) : null}
        </Box>
        <Stack direction="row" spacing={0.5} alignItems="center" sx={{ color: toneText(info.tone), display: { xs: 'none', sm: 'flex' } }}>
          <Icon name={info.icon} size={14} />
          <Typography variant="caption" sx={{ fontWeight: 700 }}>
            {info.label}
          </Typography>
        </Stack>
        <Tooltip title={HEADSET[headset].label} arrow>
          <Box component="span" role="img" aria-label={HEADSET[headset].label} sx={{ display: 'flex', color: toneColor(HEADSET[headset].tone) }}>
            <Icon name={HEADSET[headset].icon} size={15} />
          </Box>
        </Tooltip>
        <ActionIcon icon="lucide:user-cog" label={`Manage queues for ${member.name}`} onClick={() => openAgentQueues(member.user)} />
      </Stack>
    </Box>
  );
}
