/**
 * Queue presentation rules: wait bands, ring strategy labels, KPIs.
 */
import type { AgentRow, QueueView } from '../types';
import { ON_CALL_STATES } from './agents';
import { callerWaitSeconds } from './calls';

/** Platform thresholds (seconds). Inclusive at each edge. */
export const LONG_WAIT_SECONDS = 120;
export const CRITICAL_WAIT_SECONDS = 180;

export type WaitBand = 'ok' | 'long' | 'critical';

export function waitBand(
  seconds: number,
  thresholds: { long: number; critical: number } = { long: LONG_WAIT_SECONDS, critical: CRITICAL_WAIT_SECONDS },
): WaitBand {
  if (!Number.isFinite(seconds) || seconds < 0) return 'ok';
  const critical = Math.max(thresholds.critical, thresholds.long);
  if (seconds >= critical) return 'critical';
  if (seconds >= thresholds.long) return 'long';
  return 'ok';
}

export const BAND_LABEL: Record<WaitBand, string> = {
  ok: 'Waiting',
  long: 'Long wait',
  critical: 'Critical wait',
};

export const BAND_TONE: Record<WaitBand, 'success' | 'warning' | 'error'> = {
  ok: 'success',
  long: 'warning',
  critical: 'error',
};

const RING_LABELS: Record<string, string> = {
  '1stavail': 'Round-robin',
  roundrobin: 'Tiered Round-robin',
  simultaneous: 'Ring All',
  linear: 'Linear Hunt',
  sringordered: 'Linear Cascade',
  sring: 'Sequential Ring',
  random: 'Random',
  'round-robin': 'Round-robin',
  'tiered-round-robin': 'Tiered Round-robin',
  'ring-all': 'Ring All',
  'linear-hunt': 'Linear Hunt',
  'linear-cascade': 'Linear Cascade',
  'sequential-ring': 'Sequential Ring',
  'call-park': 'Call Park',
  park: 'Call Park',
};

export function ringStrategyLabel(dispatchType: string): string {
  const k = (dispatchType ?? '').trim().toLowerCase();
  if (!k || k === '-') return '';
  if (RING_LABELS[k]) return RING_LABELS[k];
  return k.replace(/[-_]+/g, ' ').replace(/\b\w/g, (c) => c.toUpperCase());
}

/** Entry-order badges only make sense for ordered strategies. */
export function showsEntryOrder(dispatchType: string): boolean {
  const l = ringStrategyLabel(dispatchType);
  return l === 'Linear Hunt' || l === 'Linear Cascade' || l === 'Sequential Ring';
}

export function isParkQueue(dispatchType: string): boolean {
  return /park/i.test(dispatchType ?? '');
}

/** Waiting count: detail rows when we have them, else the switch's counter. */
export function waitingCount(q: QueueView): number {
  if (q.streamWaiting != null) return q.streamWaiting;
  const real = q.waiting.filter((c) => !c.placeholder).length;
  return real > 0 ? real : q.reportedWaiting;
}

export function longestWaitSeconds(q: QueueView, now: number): number {
  if (q.streamWaiting === 0) return 0;
  let max = q.streamOldestAt ? Math.max(0, Math.floor((now - q.streamOldestAt) / 1000)) : 0;
  for (const c of q.waiting) {
    if (c.placeholder) continue;
    max = Math.max(max, callerWaitSeconds(c, now));
  }
  return max;
}

export interface Kpis {
  waiting: number;
  longestSeconds: number;
  available: number;
  onCall: number;
}

export function deriveKpis(queues: QueueView[], rows: AgentRow[], now: number): Kpis {
  let waiting = 0;
  let longest = 0;
  for (const q of queues) {
    if (q.isPark) continue;
    waiting += waitingCount(q);
    longest = Math.max(longest, longestWaitSeconds(q, now));
  }
  return {
    waiting,
    longestSeconds: longest,
    available: rows.filter((r) => r.state === 'idle').length,
    onCall: rows.filter((r) => ON_CALL_STATES.has(r.state)).length,
  };
}
