/**
 * Stream events drawn straight onto the board.
 *
 * The board's call records come from GET /domains/:d/calls: they carry the
 * switch's per-leg call ids that hold, transfer and park need. Flow's
 * `calls.*` streams arrive first but in a smaller shape (one `callId`, one
 * call-level state). So the board shows the API's records, and the stream
 * corrects them in between reads:
 *
 *   - a record the stream says changed shows the stream's state
 *   - a record the stream says ended disappears
 *   - a call the stream has and the API does not yet shows as a provisional
 *     leg (no control ids, so its buttons wait) until the next read
 *
 * Every correction is dropped once an API read SENT after the event returns,
 * so a stream payload that maps differently than expected costs at most one
 * read's lag and never leaves a duplicate or a ghost behind.
 */
import type { CallActivity, QueueStats } from '@netsapiens/flow-sdk';

import type { CallLeg, NsCallQueue } from '../types';
import { digitsOf } from '../model/raw';

export interface Seen<T> {
  value: T;
  /** When the event arrived (local clock). */
  at: number;
}

export interface CallOverlay {
  /** Calls the stream reports in progress, by callId. */
  live: Map<string, Seen<CallActivity>>;
  /** Calls the stream reported ended, by callId. */
  ended: Map<string, Seen<CallActivity>>;
}

export function emptyCallOverlay(): CallOverlay {
  return { live: new Map(), ended: new Map() };
}

/** Apply one stream event. Returns true when the board should redraw. */
export function applyCallEvent(o: CallOverlay, kind: 'updated' | 'ended', c: CallActivity, at: number): boolean {
  if (!c || typeof c.callId !== 'string' || !c.callId) return false;
  if (kind === 'ended') {
    o.live.delete(c.callId);
    o.ended.set(c.callId, { value: c, at });
  } else {
    o.ended.delete(c.callId);
    o.live.set(c.callId, { value: c, at });
  }
  return true;
}

/** Forget what an API read sent at `sentAt` has superseded. */
export function settleCallOverlay(o: CallOverlay, sentAt: number, readLegs: CallLeg[]): void {
  for (const [id, s] of o.ended) if (s.at < sentAt) o.ended.delete(id);
  // A live entry the read could not place is either over or maps differently
  // than expected; the read wins either way. Matched ones stay, so the next
  // state change still has something to correct.
  for (const [id, s] of o.live) {
    if (s.at < sentAt && !readLegs.some((l) => sameCall(l, s.value))) o.live.delete(id);
  }
}

const partyNumber = (p: { user?: string; number?: string } | undefined) => digitsOf(p?.number ?? '');

/** Does the API record `leg` describe the stream's call `c`? */
export function sameCall(leg: CallLeg, c: CallActivity): boolean {
  if (!c.callId) return false;
  if ([leg.origId, leg.termId, leg.sessionId, ...leg.controlIds].includes(c.callId)) return true;
  // No shared id: the same two parties, started within a few seconds.
  const fromUser = c.from?.user ?? '';
  const fromOk = fromUser ? fromUser === leg.origUser : !!partyNumber(c.from) && partyNumber(c.from) === digitsOf(leg.origNumber);
  if (!fromOk) return false;
  const toUser = c.to?.user ?? '';
  const toOk = toUser ? toUser === leg.termUser || toUser === leg.throughUser : true;
  if (!toOk) return false;
  const started = Date.parse(c.startedAt);
  if (!Number.isFinite(started) || leg.startedAt == null) return true;
  // The API's times are the switch's local time without a zone, so a record
  // can read whole hours (or a quarter-hour zone) off: compare modulo 15 min.
  const diff = Math.abs(started - leg.startedAt);
  const off = diff % 900_000;
  return diff < 14 * 3_600_000 && (off < 10_000 || off > 890_000);
}

function info(state: CallActivity['state']): string {
  return state === 'held' ? 'held' : state === 'ringing' ? 'alerting' : 'active';
}

/** A leg for a call the API has not returned yet. No control ids: display only. */
export function provisionalLeg(c: CallActivity): CallLeg {
  const answeredAt = c.answeredAt ? Date.parse(c.answeredAt) : NaN;
  const startedAt = Date.parse(c.startedAt);
  const state = info(c.state);
  return {
    key: `stream:${c.callId}`,
    controlIds: [],
    origId: '',
    termId: '',
    sessionId: '',
    origUser: c.from?.user ?? '',
    origName: c.from?.name ?? '',
    origNumber: c.from?.number ?? '',
    termUser: c.to?.user ?? '',
    termName: c.to?.name ?? '',
    throughUser: c.through?.user ?? '',
    throughName: c.through?.name ?? '',
    throughAction: c.through?.action ?? '',
    dialed: c.to?.user ? '' : c.to?.number ?? '',
    termUri: '',
    origInfo: state,
    termInfo: c.state === 'ringing' && !c.to?.user ? '' : state,
    startedAt: Number.isFinite(startedAt) ? startedAt : null,
    answeredAt: Number.isFinite(answeredAt) ? answeredAt : null,
    raw: { stream: c },
    provisional: true,
  };
}

/**
 * The board's calls: the API read sent at `sentAt`, corrected by stream events
 * that arrived after it.
 */
export function mergeCalls(read: CallLeg[], o: CallOverlay, sentAt: number): CallLeg[] {
  const out: CallLeg[] = [];
  const placed = new Set<string>();
  for (const leg of read) {
    const gone = [...o.ended.values()].find((s) => s.at >= sentAt && sameCall(leg, s.value));
    if (gone) {
      placed.add(gone.value.callId);
      continue;
    }
    const live = [...o.live.values()].find((s) => sameCall(leg, s.value));
    if (!live) {
      out.push(leg);
      continue;
    }
    placed.add(live.value.callId);
    if (live.at < sentAt) {
      out.push(leg);
      continue;
    }
    const c = live.value;
    const state = info(c.state);
    const answeredAt = c.answeredAt ? Date.parse(c.answeredAt) : NaN;
    out.push({
      ...leg,
      origInfo: state,
      termInfo: leg.termUser || c.state !== 'ringing' ? state : leg.termInfo,
      answeredAt: Number.isFinite(answeredAt) ? answeredAt : leg.answeredAt,
    });
  }
  for (const s of o.live.values()) {
    if (s.at >= sentAt && !placed.has(s.value.callId)) out.push(provisionalLeg(s.value));
  }
  return out;
}

export const STREAM_WAITING = 'stream-waiting';
export const STREAM_OLDEST = 'stream-oldest-queued-at';

/** Queue counts from the stream, newer than the read sent at `sentAt`. */
export function mergeQueueStats(rows: NsCallQueue[], stats: Map<string, Seen<QueueStats>>, sentAt: number): NsCallQueue[] {
  if (!stats.size) return rows;
  return rows.map((r) => {
    const s = stats.get(String(r.callqueue ?? ''));
    if (!s || s.at < sentAt) return r;
    const q = s.value;
    return {
      ...r,
      'active-queued-calls-total-current': q.waiting,
      'callqueue-count-agents-available': q.agentsAvailable,
      agent_loggedin_count: q.agentsLoggedIn,
      // Fresher than any caller list the API returned, so the board counts these.
      [STREAM_WAITING]: q.waiting,
      [STREAM_OLDEST]: q.oldestQueuedAt ? Date.parse(q.oldestQueuedAt) : null,
    };
  });
}
