/**
 * Agents: roster normalisation, the ten-state agent model, the headset verdict
 * and the Operate person roster. Rules follow the Engage switchboard
 * (consoleAdapter, operationsConsoleModel, headsetState, agentAvailability).
 */
import type {
  AgentRow,
  AgentState,
  Contact,
  HeadsetState,
  Line,
  NsAgent,
  QueueMember,
  QueueView,
} from '../types';
import { explicitNo, first, lower, parseSwitchTime, pick, toInt, toIntOrUndef, userPart } from './raw';

/** "1000@dom" -> "1000@dom"; "1000" -> "1000@dom". The switch refuses a bare ext. */
export function agentId(user: string, domain: string): string {
  return user.includes('@') ? user : `${user}@${domain}`;
}

export function agentUser(a: NsAgent): string {
  return userPart(first(a['callqueue-agent-id'], a['login-username']));
}

export function availabilityStatus(dispatch: string, activeCalls: number): QueueMember['status'] {
  if (dispatch === 'available') return activeCalls > 0 ? 'on-call' : 'available';
  return activeCalls > 0 ? 'on-call' : 'unavailable';
}

export function takingCallsOf(a: NsAgent): boolean | undefined {
  const t = lower(a['callqueue-agent-availability-type']);
  if (!t) return undefined;
  return t === 'automatic' || t === 'offnet-automatic';
}

/** Normalise one roster row. `contactName` resolves a nameless entry. */
export function toQueueMember(a: NsAgent, queue: string, contactName?: string): QueueMember {
  const user = agentUser(a);
  const dispatch = lower(a['callqueue-agent-availability-for-dispatch']);
  const activeCalls = toInt(a['active-calls-total-current']);
  const fullName = first(
    a['name-full-name'],
    contactName,
    `${a['name-first-name'] ?? ''} ${a['name-last-name'] ?? ''}`.trim(),
    user,
  );
  return {
    queue: first(a.callqueue, queue),
    user,
    agentId: pick(a, 'callqueue-agent-id', 'login-username'),
    name: fullName,
    status: availabilityStatus(dispatch, activeCalls),
    takingCalls: takingCallsOf(a),
    loggedOut: lower(a['callqueue-agent-entry-type']) === 'dnd',
    hasDevice: !explicitNo(a['callqueue-agent-has-registered-devices']),
    activeCalls,
    callLimit: toIntOrUndef(a['limits-max-active-calls-total'] ?? a.call_limit),
    entryOrder: toIntOrUndef(a['callqueue-agent-dispatch-order-ordinal']),
    portalStatus: first(a['agent-status-message'], a['status-message']).replace(/^[\s-]+/, ''),
    lastModified: parseSwitchTime(a['last-modified-datetime']),
    raw: a,
  };
}

/** Is a member "taking calls" from the queue (the switch's toggle, else routability)? */
export function memberLoggedIn(m: QueueMember): boolean {
  return m.takingCalls ?? m.status !== 'unavailable';
}

/** Routable = would receive the next call: not DND, not logged out, available and idle. */
export function isRoutable(m: QueueMember, handsetDnd: boolean): boolean {
  return !handsetDnd && !m.loggedOut && m.status === 'available';
}

export function routableCount(roster: QueueMember[], dndByUser: Map<string, boolean>): number {
  return roster.filter((m) => isRoutable(m, dndByUser.get(m.user) ?? false)).length;
}

// ---------------------------------------------------------------------------
// Agent state (Operate roster, KPI strip, wallboard dots)
// ---------------------------------------------------------------------------

export interface AgentStateInfo {
  label: string;
  /** Semantic tone for dots/chips. */
  tone: 'success' | 'warning' | 'info' | 'error' | 'neutral';
  icon: string;
  routable: boolean;
}

export const AGENT_STATE: Record<AgentState, AgentStateInfo> = {
  idle: { label: 'Idle', tone: 'success', icon: 'lucide:check', routable: true },
  ringing: { label: 'Ringing', tone: 'warning', icon: 'lucide:bell-ring', routable: false },
  inbound: { label: 'Inbound', tone: 'info', icon: 'lucide:phone-incoming', routable: false },
  outbound: { label: 'Outbound', tone: 'info', icon: 'lucide:phone-outgoing', routable: false },
  'on-call': { label: 'On call', tone: 'info', icon: 'lucide:phone', routable: false },
  hold: { label: 'Hold', tone: 'warning', icon: 'lucide:pause', routable: false },
  'wrap-up': { label: 'Wrap-up', tone: 'warning', icon: 'lucide:timer', routable: false },
  'logged-out': { label: 'Logged out', tone: 'neutral', icon: 'lucide:log-out', routable: false },
  dnd: { label: 'DND', tone: 'error', icon: 'lucide:phone-off', routable: false },
  offline: { label: 'Offline', tone: 'neutral', icon: 'lucide:circle-off', routable: false },
};

/**
 * First match wins: offline > dnd > a live line > on-call > logged out >
 * wrap-up > idle.
 */
export function resolveAgentState(
  lines: Line[],
  status: QueueMember['status'] | undefined,
  opts: { dnd: boolean; loggedOut: boolean; offline: boolean },
): AgentState {
  if (opts.offline) return 'offline';
  if (opts.dnd) return 'dnd';
  const primary = lines[0];
  if (primary) {
    if (primary.status === 'held') return 'hold';
    if (primary.status === 'ringing' || primary.status === 'dialing' || primary.answeredAt == null) return 'ringing';
    return primary.direction === 'outbound' ? 'outbound' : 'inbound';
  }
  if (status === 'on-call') return 'on-call';
  if (opts.loggedOut) return 'logged-out';
  if (status === 'unavailable') return 'wrap-up';
  return 'idle';
}

export const ON_CALL_STATES: ReadonlySet<AgentState> = new Set(['inbound', 'outbound', 'hold', 'on-call']);

// ---------------------------------------------------------------------------
// Headset verdict
// ---------------------------------------------------------------------------

export const HEADSET: Record<HeadsetState, { icon: string; label: string; tone: AgentStateInfo['tone'] }> = {
  free: { icon: 'lucide:headphones', label: 'Free to take a call', tone: 'success' },
  amber: { icon: 'lucide:headset', label: 'On a call, still taking queue calls', tone: 'warning' },
  busy: { icon: 'lucide:headphone-off', label: 'Not taking queue calls', tone: 'error' },
  missing: { icon: 'lucide:circle-help', label: 'No headset state reported', tone: 'neutral' },
};

const ENGAGED = new Set(['inuse', 'held', 'hold', 'alerting', 'progressing', 'ringing']);

export function isEngagedPresence(p: string): boolean {
  return ENGAGED.has(p);
}

/**
 * The headset verdict for a person. `agent` aggregates their memberships:
 * available = any membership routable, sessions = max active calls. `null`
 * when they are in no queue.
 */
export function headsetStateFor(
  presence: string,
  agent: { available: boolean; sessions: number } | null,
  hasDevice?: boolean,
): HeadsetState {
  if (hasDevice === false) return 'missing';
  if (presence === 'closed') return 'busy';
  if (agent && agent.sessions > 0) return agent.available ? 'amber' : 'busy';
  if (isEngagedPresence(presence)) {
    if (!agent) return 'busy';
    return agent.available ? 'amber' : 'busy';
  }
  if (presence === 'open' || presence === 'available' || presence === '') {
    if (!agent) return 'missing';
    return agent.available ? 'free' : 'busy';
  }
  return 'missing';
}

export interface HeadsetSummary {
  state: HeadsetState;
  title: string;
  subtitle: string;
}

export function summariseHeadset(presence: string, memberships: QueueMember[], lines: Line[]): HeadsetSummary {
  const available = memberships.some((m) => m.status === 'available' && !m.loggedOut);
  const sessions = memberships.reduce((mx, m) => Math.max(mx, m.activeCalls), 0);
  const state = headsetStateFor(presence, memberships.length ? { available, sessions } : null);
  const ringing = /alerting|progressing|ringing/.test(presence) || lines.some((l) => l.status === 'ringing');
  const onCall = isEngagedPresence(presence) || sessions > 0 || lines.length > 0;
  if (onCall) {
    return {
      state,
      title: ringing ? 'Ringing' : 'On a call',
      subtitle: available ? 'Can take another queue call' : 'No queue will route another call',
    };
  }
  if (memberships.length && available) {
    const n = memberships.filter((m) => m.status === 'available' && !m.loggedOut).length;
    return { state, title: 'Available', subtitle: `Idle, ready in ${n} queue${n === 1 ? '' : 's'}` };
  }
  if (memberships.length) {
    return {
      state,
      title: presence === 'closed' ? 'Do Not Disturb' : 'Logged out of queues',
      subtitle: 'Phone idle, not accepting queue calls',
    };
  }
  return { state, title: 'No queue memberships', subtitle: 'Not an agent in any call queue' };
}

/** "S of L calls" / "S calls" / "limit L" for a membership row. */
export function callsLabel(m: QueueMember): string {
  if (m.callLimit != null && m.callLimit > 0) {
    return m.activeCalls > 0 ? `${m.activeCalls} of ${m.callLimit} call${m.callLimit === 1 ? '' : 's'}` : `limit ${m.callLimit}`;
  }
  return m.activeCalls > 0 ? `${m.activeCalls} call${m.activeCalls === 1 ? '' : 's'}` : '';
}

// ---------------------------------------------------------------------------
// The person roster (Operate + KPI strip)
// ---------------------------------------------------------------------------

/**
 * One row per person across every queue. Membership detail comes from the
 * per-queue rosters when loaded; the domain `/agents` read (one row per agent)
 * fills in people whose queue roster has not loaded yet, so the roster and the
 * KPI counts are right from the first poll.
 */
export function buildAgentRows(
  queues: QueueView[],
  domainAgents: NsAgent[],
  contactsByUser: Map<string, Contact>,
): AgentRow[] {
  const members = new Map<string, QueueMember[]>();
  const queueNames = new Map(queues.map((q) => [q.ext, q.name] as const));
  const canonical = (u: string): string => {
    if (contactsByUser.has(u)) return u;
    const m = /^(\d+)[a-z]{1,2}$/i.exec(u);
    return m && contactsByUser.has(m[1]) ? m[1] : u;
  };

  for (const q of queues) {
    for (const m of q.roster ?? []) {
      const u = canonical(m.user);
      const list = members.get(u) ?? [];
      list.push(m);
      members.set(u, list);
    }
  }
  // People the rosters have not covered yet, from the one-row-per-agent read.
  for (const a of domainAgents) {
    const u = canonical(agentUser(a));
    if (!u || members.has(u)) continue;
    const queueList = (a.queue_list ?? a.callqueue ?? '')
      .split(',')
      .map((s) => s.trim())
      .filter(Boolean);
    const contact = contactsByUser.get(u);
    const base = toQueueMember(a, queueList[0] ?? '', contact?.name);
    members.set(
      u,
      (queueList.length ? queueList : [base.queue]).map((q) => ({ ...base, queue: q })),
    );
  }

  // Every queue a person belongs to, from the one-row-per-agent read, so the
  // queue list is complete even before every roster has loaded.
  const listed = new Map<string, string[]>();
  for (const a of domainAgents) {
    const u = canonical(agentUser(a));
    if (!u) continue;
    const qs = String(a.queue_list ?? a.callqueue ?? '')
      .split(',')
      .map((s) => s.trim())
      .filter(Boolean);
    listed.set(u, Array.from(new Set([...(listed.get(u) ?? []), ...qs])));
  }

  const rows: AgentRow[] = [];
  for (const [user, list] of members) {
    const contact = contactsByUser.get(user) ?? null;
    const firstM = list[0];
    const lines = contact?.lines ?? [];
    const state = resolveAgentState(lines, firstM?.status, {
      dnd: contact?.dnd ?? false,
      loggedOut: list.every((m) => m.loggedOut),
      offline: list.every((m) => !m.hasDevice),
    });
    const routable = list.filter((m) => isRoutable(m, contact?.dnd ?? false)).length;
    const primary = lines[0];
    const since = primary ? primary.answeredAt ?? primary.startedAt : contact?.lastUpdate ?? firstM?.lastModified ?? null;

    let headset: HeadsetState;
    if (state === 'offline') headset = 'missing';
    else {
      const presence = state === 'dnd' ? 'closed' : state === 'idle' || state === 'logged-out' ? 'open' : 'inuse';
      headset = headsetStateFor(presence, { available: routable > 0, sessions: 0 });
      if (presence === 'inuse') headset = routable > 0 ? 'amber' : 'busy';
    }

    rows.push({
      user,
      name: first(firstM?.name, contact?.name, user),
      state,
      since,
      peerName: primary?.peerName ?? '',
      peerNumber: primary?.peerNumber ?? '',
      extraCalls: Math.max(0, lines.length - 1),
      queues: Array.from(
        new Set([...list.map((m) => m.queue), ...(listed.get(user) ?? [])].map((q) => queueNames.get(q) ?? q)),
      ),
      routable,
      headset,
      portalStatus: first(contact?.portalStatus, firstM?.portalStatus),
      contact,
    });
  }
  const rank = (s: AgentState) => (s === 'idle' ? 0 : s === 'offline' ? 2 : 1);
  rows.sort((a, b) => rank(a.state) - rank(b.state) || a.name.localeCompare(b.name));
  return rows;
}

// ---------------------------------------------------------------------------
// The operator's own status (header switcher)
// ---------------------------------------------------------------------------

export const DEFAULT_STATUS_OPTIONS = [
  'Online',
  'Offline',
  'Break',
  'Lunch',
  'Meeting',
  'Do Not Disturb',
  'Single Call',
  'End Shift',
] as const;

export function statusTone(status: string): 'success' | 'neutral' | 'warning' {
  if (status === 'Online' || status === '') return 'success';
  if (status === 'Offline' || status === 'End Shift') return 'neutral';
  return 'warning';
}

export function resolveCurrentStatus(me: NsAgent | null, myPresence: string): string {
  if (!me) return '';
  const msg = first(me['agent-status-message'], me['status-message']);
  if (msg) return msg;
  if (myPresence === 'closed') return 'Do Not Disturb';
  const t = lower(me['callqueue-agent-availability-type']);
  if (!t) return lower(me['callqueue-agent-availability-for-dispatch']) === 'available' ? 'Online' : 'Offline';
  return t === 'automatic' || t === 'offnet-automatic' ? 'Online' : 'Offline';
}
