/**
 * Operate mode (the Engage OperationsConsole), for supervisors:
 *   left     every queue with its waiting count and a staffing bar
 *   centre   waiting callers across all queues, longest first,
 *            then the agent roster (state, age, queues, headset, manage)
 * The operator rail (My Calls / Call Parks / Dial Pad) sits to the right,
 * drawn by the shell.
 */
import { useMemo, useState } from 'react';

import type { AgentRow, QueueCaller, QueueView } from '../../types';
import { useSwitchboard } from '../../data/SwitchboardData';
import { usePanels } from '../../data/panels';
import { useNow } from '../../data/clock';
import { isBoolean, usePersistentState } from '../../data/persist';
import { BLOCKED } from '../../api/ns';
import { AGENT_STATE, HEADSET, ON_CALL_STATES } from '../../model/agents';
import { callerWaitSeconds } from '../../model/calls';
import { formatDateTime, formatElapsed, formatPhone, formatStateAge } from '../../model/format';
import { BAND_LABEL, BAND_TONE, longestWaitSeconds, waitBand, waitingCount } from '../../model/queues';
import { useKit } from '../../ui/kit';
import { ActionIcon, BlockedButton, Dot, Empty, Pill, SectionTitle, tint, toneColor, toneText } from '../../ui/bits';
import { queueAgentCounts } from '../realtime/QueueTile';

export function OperateView() {
  const { Box, Stack, Button, Icon } = useKit();
  const { caps } = useSwitchboard();
  const [showQueues, setShowQueues] = usePersistentState<boolean>('op.showQueues', true, isBoolean);

  return (
    <Box sx={{ display: 'flex', gap: 2, alignItems: 'flex-start' }}>
      {showQueues ? (
        <Box sx={{ width: 300, flexShrink: 0, display: { xs: 'none', md: 'block' } }}>
          <QueueList onCollapse={() => setShowQueues(false)} />
        </Box>
      ) : (
        <Box sx={{ display: { xs: 'none', md: 'block' } }}>
          <Button
            size="small"
            color="inherit"
            onClick={() => setShowQueues(true)}
            startIcon={<Icon name="lucide:panel-left-open" size={16} />}
            sx={{ textTransform: 'none' }}
          >
            Show queues
          </Button>
        </Box>
      )}
      <Stack spacing={2.5} sx={{ flex: 1, minWidth: 0, maxWidth: 1024, mx: 'auto' }}>
        <WaitingCallers />
        {caps.agentRoster ? <AgentRoster /> : null}
      </Stack>
    </Box>
  );
}

// ---------------------------------------------------------------------------
// Queue list
// ---------------------------------------------------------------------------

function QueueList({ onCollapse }: { onCollapse: () => void }) {
  const { Stack } = useKit();
  const { queues } = useSwitchboard();
  return (
    <Stack spacing={1}>
      <SectionTitle
        icon="lucide:list-ordered"
        title="Queues"
        right={<ActionIcon icon="lucide:panel-left-close" label="Collapse queues" onClick={onCollapse} />}
      />
      {queues.length === 0 ? <Empty>No queues</Empty> : queues.map((q) => <QueueCard key={q.ext} queue={q} />)}
    </Stack>
  );
}

function QueueCard({ queue }: { queue: QueueView }) {
  const now = useNow();
  const { Paper, Stack, Typography, Box } = useKit();
  const { caps, contacts } = useSwitchboard();
  const { openStaffing, openQueue } = usePanels();
  const dnd = useMemo(() => new Map(contacts.map((c) => [c.user, c.dnd] as const)), [contacts]);
  const { available, total } = queueAgentCounts(queue, dnd);
  const waiting = waitingCount(queue);
  const band = waitBand(longestWaitSeconds(queue, now));
  const pct = total > 0 ? Math.round((available / total) * 100) : 0;
  const waitColor = waiting > 0 ? (band === 'critical' ? 'error.main' : 'text.primary') : 'text.disabled';
  return (
    <Paper variant="outlined" sx={{ p: 1.25 }}>
      <Stack direction="row" alignItems="baseline" spacing={0.75}>
        <Typography
          variant="body2"
          component="button"
          onClick={() => openQueue(queue.ext)}
          title="Open this queue"
          sx={{ all: 'unset', cursor: 'pointer', fontWeight: 700, flex: 1, minWidth: 0, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', '&:hover': { textDecoration: 'underline' } }}
        >
          {queue.name}
        </Typography>
        <Typography sx={{ fontSize: 10, color: 'text.secondary' }}>{queue.ext}</Typography>
        <Typography sx={{ fontWeight: 800, fontVariantNumeric: 'tabular-nums', color: waitColor, minWidth: 18, textAlign: 'right' }}>
          {waiting}
        </Typography>
      </Stack>
      <Stack direction="row" alignItems="center" spacing={1} sx={{ mt: 0.75 }}>
        <Box
          role="img"
          aria-label={`${available} of ${total} agents available`}
          sx={{ flex: 1, height: 6, borderRadius: 3, bgcolor: 'action.selected', overflow: 'hidden' }}
        >
          <Box sx={{ width: `${pct}%`, height: '100%', bgcolor: 'success.main' }} />
        </Box>
        <Typography sx={{ fontSize: 11, color: 'text.secondary', fontVariantNumeric: 'tabular-nums' }}>
          {available}/{total}
        </Typography>
        {caps.manageQueueAgents ? (
          <ActionIcon icon="lucide:user-plus" label={`Staff the ${queue.name} queue`} onClick={() => openStaffing(queue.ext)} />
        ) : null}
      </Stack>
    </Paper>
  );
}

// ---------------------------------------------------------------------------
// Waiting callers
// ---------------------------------------------------------------------------

function WaitingCallers() {
  const now = useNow();
  const { Stack } = useKit();
  const { queues } = useSwitchboard();
  const rows = useMemo(() => {
    const out: Array<{ caller: QueueCaller; queue: QueueView }> = [];
    for (const q of queues) for (const c of q.waiting) out.push({ caller: c, queue: q });
    return out;
  }, [queues]);
  const sorted = [...rows].sort((a, b) => callerWaitSeconds(b.caller, now) - callerWaitSeconds(a.caller, now));
  return (
    <section aria-label="Waiting callers">
      <SectionTitle icon="lucide:phone-incoming" title="Waiting callers" caption="all queues, longest first" count={sorted.length} countTone="warning" />
      {sorted.length === 0 ? (
        <Empty>No callers waiting.</Empty>
      ) : (
        <Stack spacing={0.75}>
          {sorted.map(({ caller, queue }) => (
            <WaitingRow key={caller.key} caller={caller} queue={queue} now={now} />
          ))}
        </Stack>
      )}
    </section>
  );
}

function WaitingRow({ caller, queue, now }: { caller: QueueCaller; queue: QueueView; now: number }) {
  const { Box, Stack, Typography } = useKit();
  const wait = callerWaitSeconds(caller, now);
  const band = waitBand(wait);
  const tone = BAND_TONE[band];
  const number = caller.callerNumber ? formatPhone(caller.callerNumber) : '';
  const hasName = caller.callerName && caller.callerName !== number && caller.callerName !== 'Unknown';
  return (
    <Box
      sx={{
        display: 'flex',
        alignItems: 'center',
        gap: 1.5,
        px: 1.25,
        py: 0.75,
        borderRadius: 1.5,
        border: 1,
        borderColor: band === 'ok' ? 'divider' : tint(tone, 0.4),
        bgcolor: band === 'ok' ? 'background.paper' : tint(tone, 0.1),
      }}
    >
      <Box sx={{ width: 4, height: 36, borderRadius: 2, bgcolor: toneColor(tone), flexShrink: 0 }} />
      <Box sx={{ width: 96, flexShrink: 0 }}>
        <Typography sx={{ fontWeight: 800, fontVariantNumeric: 'tabular-nums' }}>
          {caller.placeholder ? '-' : formatElapsed(wait)}
        </Typography>
        <Typography sx={{ fontSize: 10, fontWeight: 700, letterSpacing: 0.6, textTransform: 'uppercase', color: toneText(tone) }}>
          {BAND_LABEL[band]}
        </Typography>
      </Box>
      <Box sx={{ flex: 1, minWidth: 0 }}>
        <Typography variant="body2" sx={{ fontWeight: 600 }} noWrap>
          {hasName ? caller.callerName : number || caller.callerName}
        </Typography>
        <Typography variant="caption" color="text.secondary" noWrap sx={{ display: 'block' }}>
          {hasName ? number || 'No number' : 'No caller name'}
        </Typography>
      </Box>
      <Pill label={queue.name} title={`Queue ${queue.ext}`} />
      <Stack direction="row">
        <BlockedButton icon="lucide:phone-call" label="Take" reason={BLOCKED.pickup} />
      </Stack>
    </Box>
  );
}

// ---------------------------------------------------------------------------
// Agent roster
// ---------------------------------------------------------------------------

function AgentRoster() {
  const { Stack, Box, SearchField, Paper, Typography, Button, Icon, Divider } = useKit();
  const { agentRows } = useSwitchboard();
  const [hideOffline, setHideOffline] = useState(true);
  const [query, setQuery] = useState('');

  const available = agentRows.filter((r) => r.state === 'idle').length;
  const onCall = agentRows.filter((r) => ON_CALL_STATES.has(r.state)).length;

  const q = query.trim().toLowerCase();
  const matches = agentRows.filter((r) => !q || r.name.toLowerCase().includes(q) || r.user.toLowerCase().includes(q));
  const filterSuspended = !!q && hideOffline;
  const shown = !q && hideOffline ? matches.filter((r) => r.state !== 'offline') : matches;
  const hiddenOffline = matches.length - shown.length;

  return (
    <section aria-label="Agents">
      <SectionTitle
        icon="lucide:users"
        title="Agents"
        right={
          <Stack direction="row" spacing={1} alignItems="center">
            <Pill tone="success" outlined label={`${available} available`} />
            <Pill tone="info" outlined label={`${onCall} on call`} />
            <Button
              size="small"
              variant={hideOffline ? 'contained' : 'outlined'}
              color={hideOffline ? 'primary' : 'inherit'}
              aria-pressed={hideOffline}
              onClick={() => setHideOffline((v) => !v)}
              startIcon={<Icon name="lucide:eye-off" size={14} />}
              sx={{ textTransform: 'none', whiteSpace: 'nowrap' }}
            >
              Hide offline
            </Button>
            <Box sx={{ width: 220 }}>
              <SearchField size="small" fullWidth value={query} onChange={setQuery} onClear={() => setQuery('')} placeholder="Name or extension" />
            </Box>
          </Stack>
        }
      />
      <Paper variant="outlined" sx={{ overflow: 'hidden' }}>
        {shown.length === 0 ? (
          <Box sx={{ p: 2.5, textAlign: 'center' }}>
            <Typography variant="body2" color="text.secondary">
              {q ? `No agent matches "${query.trim()}".` : hiddenOffline > 0 ? 'Every agent is offline.' : 'No agents are assigned to a queue.'}
            </Typography>
          </Box>
        ) : (
          <Stack divider={<Divider />}>
            {shown.map((r) => (
              <AgentLine key={r.user} row={r} />
            ))}
          </Stack>
        )}
        {hiddenOffline > 0 && !q ? (
          <Stack direction="row" alignItems="center" spacing={1} sx={{ px: 2, py: 1, borderTop: 1, borderColor: 'divider' }}>
            <Typography variant="caption" color="text.secondary">
              {hiddenOffline} offline hidden
            </Typography>
            <Button size="small" variant="text" onClick={() => setHideOffline(false)} sx={{ textTransform: 'none' }}>
              Show all
            </Button>
          </Stack>
        ) : null}
        {filterSuspended ? (
          <Box sx={{ px: 2, py: 1, borderTop: 1, borderColor: 'divider' }}>
            <Typography variant="caption" color="text.secondary">
              Showing offline agents too, because you are searching.
            </Typography>
          </Box>
        ) : null}
      </Paper>
    </section>
  );
}

function AgentLine({ row }: { row: AgentRow }) {
  const now = useNow();
  const { Stack, Box, Typography, Icon, Tooltip } = useKit();
  const { caps } = useSwitchboard();
  const { openAgentQueues } = usePanels();
  const info = AGENT_STATE[row.state];
  const age = row.since != null ? formatStateAge((now - row.since) / 1000) : '';
  const peer = row.peerName || (row.peerNumber ? formatPhone(row.peerNumber) : '');
  const hs = HEADSET[row.headset];
  return (
    <Stack direction="row" alignItems="center" spacing={1.5} sx={{ px: 2, py: 1 }}>
      <Dot tone={info.tone} />
      <Box sx={{ flex: 1, minWidth: 0 }}>
        <Typography variant="body2" sx={{ fontWeight: 600 }} noWrap>
          {row.name}
          <Box component="span" sx={{ ml: 0.75, fontSize: 11, color: 'text.secondary', fontWeight: 400 }}>
            {row.user}
          </Box>
          {row.extraCalls > 0 ? (
            <Tooltip title={`${row.extraCalls} more call${row.extraCalls === 1 ? '' : 's'} on this agent`} arrow>
              <Box
                component="span"
                sx={{ ml: 0.75, px: 0.75, borderRadius: 1, fontSize: 11, fontWeight: 700, bgcolor: tint('warning', 0.15), color: 'warning.dark' }}
              >
                +{row.extraCalls}
              </Box>
            </Tooltip>
          ) : null}
        </Typography>
        {peer || row.portalStatus ? (
          <Typography variant="caption" color="text.secondary" noWrap sx={{ display: 'block' }}>
            {[peer, row.portalStatus].filter(Boolean).join(' · ')}
          </Typography>
        ) : null}
      </Box>
      <Stack direction="row" spacing={0.5} alignItems="center" sx={{ width: 104, color: 'text.secondary' }}>
        <Icon name={info.icon} size={14} />
        <Typography variant="caption" sx={{ fontWeight: 700, color: toneText(info.tone) }}>
          {info.label}
        </Typography>
      </Stack>
      <Tooltip title={row.since != null ? formatDateTime(row.since) : ''} arrow>
        <Typography variant="caption" sx={{ width: 44, textAlign: 'right', fontVariantNumeric: 'tabular-nums', color: 'text.secondary' }}>
          {age || '-'}
        </Typography>
      </Tooltip>
      <Typography variant="caption" color="text.secondary" noWrap sx={{ width: 200, display: { xs: 'none', xl: 'block' } }}>
        {row.queues.length ? row.queues.join(', ') : '-'}
      </Typography>
      <Tooltip title={hs.label} arrow>
        <Box component="span" role="img" aria-label={hs.label} sx={{ display: 'flex', color: toneColor(hs.tone) }}>
          <Icon name={hs.icon} size={16} />
        </Box>
      </Tooltip>
      {caps.manageQueueAgents ? (
        <ActionIcon icon="lucide:user-plus" label={`Manage queue membership for ${row.name}`} onClick={() => openAgentQueues(row.user)} />
      ) : null}
    </Stack>
  );
}
